            minx = min(x for y, x in cells)
            maxy = max(y for y, x in cells)
            maxx = max(x for y, x in cells)
            cellset = set(cells)
            bh, bw = maxy - miny + 1, maxx - minx + 1
            shape = {
                (y - miny, x - minx) for y, x in cells
            }

            # A shape with an enclosed zero moves upward; the others move down.
            outside = set()
            todo = []
            for yy in range(bh):
                for xx in range(bw):
                    if (yy, xx) not in shape and (
                        yy == 0 or yy == bh - 1 or xx == 0 or xx == bw - 1
                    ):
                        outside.add((yy, xx))
                        todo.append((yy, xx))
            while todo:
                yy, xx = todo.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = yy + dy, xx + dx
                    if (0 <= ny < bh and 0 <= nx < bw
                            and (ny, nx) not in shape
                            and (ny, nx) not in outside):
                        outside.add((ny, nx))
                        todo.append((ny, nx))
            has_hole = any(
                (yy, xx) not in shape and (yy, xx) not in outside
                for yy in range(bh) for xx in range(bw)
            )

            objects.append({
                "color": color,
                "cells": cells,
                "dy": -1 if has_hole else 1,
                "top": miny,
                "bottom": maxy,
            })

    # Let each class of objects settle toward its edge, stacking against
    # objects moving in the same direction.
    settled = []
    for direction in (-1, 1):
        indices = [i for i, obj in enumerate(objects) if obj["dy"] == direction]
        indices.sort(
            key=lambda i: objects[i]["top"] if direction == -1
            else -objects[i]["bottom"]
        )
        fixed = []
        for i in indices:
            cells = list(objects[i]["cells"])
            while True:
                moved = [(y + direction, x) for y, x in cells]
                if any(y < 0 or y >= h for y, x in moved):
                    break
                if any((y, x) in fixed for y, x in moved):
                    break
                cells = moved
            fixed.extend(cells)
            settled.append((objects[i]["color"], cells))

